INSERT INTO [ai_code_rule] ([id], [tenant_id], [rule_code], [rule_name], [scene], [category], [source_object_id], [source_object_code], [template], [reset_policy], [seq_length], [status], [builtin], [in_code_list], [version_no], [legacy_compat_enabled], [remark], [options], [create_by], [create_time], [create_dept], [update_by], [update_time], [del_flag]) VALUES (1910000000000008601,1,'material_code',N'物料编码','COMMON','MATERIAL',NULL,NULL,'WL${yyyyMMddHHmmss}${seq:3}','SECOND',3,1,1,1,1,1,N'适合物料编码：WL + 年月日时分秒 + 3位同秒流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000008602,1,'document_daily_no',N'通用单据日流水','COMMON','DOCUMENT',NULL,NULL,'DOC${yyyyMMdd}${seq:4}','DAY',4,1,1,1,1,1,N'适合普通业务单据：DOC + 年月日 + 4位日流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000008603,1,'order_no',N'订单编号','COMMON','DOCUMENT',NULL,NULL,'ORD${yyyyMMdd}${seq:5}','DAY',5,1,1,1,1,1,N'适合订单类单据：ORD + 年月日 + 5位日流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000008604,1,'contract_no',N'合同编号','COMMON','DOCUMENT',NULL,NULL,'HT${yyyyMM}${seq:5}','MONTH',5,1,1,1,1,1,N'适合合同类单据：HT + 年月 + 5位月流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000008605,1,'customer_code',N'客户编码','COMMON','CUSTOMER',NULL,NULL,'C${seq:6}','NONE',6,1,1,1,1,1,N'适合主数据编码：C + 6位全局流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000008606,1,'org_daily_no',N'组织日流水','COMMON','DOCUMENT',NULL,NULL,'${orgCode}${yyyyMMdd}${seq:4}','DAY',4,1,1,1,1,1,N'适合按组织隔离的日流水：组织编码 + 年月日 + 4位流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-16 20:51:34',0),(1910000000000009301,1,'supplier_code',N'供应商编号','PROCUREMENT_WAREHOUSE','SUPPLIER',NULL,NULL,'SUP${seq:5}','NONE',5,1,1,1,1,1,N'供应商主数据编号',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-16 20:51:34',0),(1910000000000009302,1,'warehouse_code',N'仓库编号','PROCUREMENT_WAREHOUSE','WAREHOUSE',NULL,NULL,'WH${seq:4}','NONE',4,1,1,1,1,1,N'仓库主数据编号',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-16 20:51:34',0),(1