INSERT INTO [ai_formula_function] ([id], [tenant_id], [function_code], [display_name], [category], [description], [source_type], [argument_schema], [return_type], [example], [status], [current_version], [latest_version], [builtin], [sort_order], [remark], [create_by], [create_time], [create_dept], [update_by], [update_time]) VALUES (690001001,1,'math.abs',N'绝对值','Math',N'返回数字绝对值','BUILTIN','[{"name": "value", "type": "NUMBER", "required": true}]','NUMBER','math.abs(-5) => 5','ENABLED','1.0.0','1.0.0',1,10,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001002,1,'math.round',N'四舍五入','Math',N'返回最接近的整数','BUILTIN','[{"name": "value", "type": "NUMBER", "required": true}]','NUMBER','math.round(3.6) => 4','ENABLED','1.0.0','1.0.0',1,20,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001003,1,'math.max',N'最大值','Math',N'返回两个数字中的最大值','BUILTIN','[{"name": "left", "type": "NUMBER", "required": true}, {"name": "right", "type": "NUMBER", "required": true}]','NUMBER','math.max(3, 7) => 7','ENABLED','1.0.0','1.0.0',1,30,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001004,1,'math.min',N'最小值','Math',N'返回两个数字中的最小值','BUILTIN','[{"name": "left", "type": "NUMBER", "required": true}, {"name": "right", "type": "NUMBER", "required": true}]','NUMBER','math.min(3, 7) => 3','ENABLED','1.0.0','1.0.0',1,40,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001005,1,'string.length',N'字符串长度','String',N'返回字符串长度','BUILTIN','[{"name": "value", "type": "STRING", "required": true}]','NUMBER','string.length(''hello'') => 5','ENABLED','1.0.0','1.0.0',1,110,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001006,1,'string.contains',N'包含判断','String',N'判断字符串是否包含子串','BUILTIN','[{"name": "value", "type": "STRING", "required": true}, {"name": "keyword", "type": "STRING", "required": true}]','BOOLEAN','string.contains(''hello'',''ll'') => true','ENABLED','1.0.0','1.0.0',1,120,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001007,1,'string.startsWith',N'前缀判断','String',N'判断字符串前缀','BUILTIN','[{"name": "value", "type": "STRING", "required": true}, {"name": "prefix", "type": "STRING", "required": true}]','BOOLEAN','string.startsWith(''hello'',''he'') => true','ENABLED','1.0.0','1.0.0',1,130,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001008,1,'string.endsWith',N'后缀判断','String',N'判断字符串后缀','BUILTIN','[{"name": "value", "type": "STRING", "required": true}, {"name": "suffix", "type": "STRING", "required": true}]','BOOLEAN','string.endsWith(''hello'',''lo'') => true','ENABLED','1.0.0','1.0.0',1,140,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001009,1,'date_to_string',N'日期格式化','Date',N'将日期格式化为字符串','BUILTIN','[{"name": "date", "type": "DATE", "required": true}, {"name": "pattern", "type": "STRING", "required": true}]','STRING','date_to_string(date, ''yyyy-MM-dd'')','ENABLED','1.0.0','1.0.0',1,210,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001010,1,'math.floor',N'向下取整','Math',N'返回不大于入参的最大整数','BUILTIN','[{"name": "value", "type": "NUMBER", "required": true}]','NUMBER','math.floor(3.9) => 3','ENABLED','1.0.0','1.0.0',1,25,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001011,1,'math.ceil',N'向上取整','Math',N'返回不小于入参的最小整数','BUILTIN','[{"name": "value", "type": "NUMBER", "required": true}]','NUMBER','math.ceil(3.1) => 4','ENABLED','1.0.0','1.0.0',1,26,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001012,1,'math.pow',N'幂运算','Math',N'返回 left 的 right 次方','BUILTIN','[{"name": "left", "type": "NUMBER", "required": true}, {"name": "right", "type": "NUMBER", "required": true}]','NUMBER','math.pow(2, 3) => 8','ENABLED','1.0.0','1.0.0',1,50,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001013,1,'math.sqrt',N'平方根','Math',N'返回数字平方根','BUILTIN','[{"name": "value", "type": "NUMBER", "required": true}]','NUMBER','math.sqrt(16) => 4','ENABLED','1.0.0','1.0.0',1,60,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001014,1,'string.indexOf',N'子串位置','String',N'返回子串首次出现位置','BUILTIN','[{"name": "value", "type": "STRING", "required": true}, {"name": "keyword", "type": "STRING", "required": true}]','NUMBER','string.indexOf(''hello'',''l'') => 2','ENABLED','1.0.0','1.0.0',1,150,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001015,1,'string.replace',N'字符串替换','String',N'替换字符串片段','BUILTIN','[{"name": "value", "type": "STRING", "required": true}, {"name": "target", "type": "STRING", "required": true}, {"name": "replacement", "type": "STRING", "required": true}]','STRING','string.replace(''hello'',''l'',''x'') => ''hexxo''','ENABLED','1.0.0','1.0.0',1,160,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001016,1,'seq.list',N'创建列表','Collection',N'按入参顺序创建列表','BUILTIN','[]','COLLECTION','seq.list(1,2,3) => [1,2,3]','ENABLED','1.0.0','1.0.0',1,310,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001017,1,'seq.set',N'创建集合','Collection',N'按入参顺序创建去重集合','BUILTIN','[]','COLLECTION','seq.set(1,2,3) => [1,2,3]','ENABLED','1.0.0','1.0.0',1,320,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16'),(690001018,1,'seq.map',N'创建映射','Collection',N'按 key/value 入参创建映射','BUILTIN','[]','MAP','seq.map(''a'',1,''b'',2) => {a:1,b:2}','ENABLED','1.0.0','1.0.0',1,330,NULL,NULL,'2026-06-14 12:57:16',NULL,NULL,'2026-06-14 12:57:16');
