INSERT INTO [ai_page_template] ([id], [template_key], [template_name], [description], [icon], [system_prompt], [schema_hint], [default_config], [enabled], [sort], [is_builtin], [codegen_type], [create_by], [create_time], [create_dept], [update_by], [update_time], [del_flag]) VALUES (1,'simple-crud',N'标准 CRUD',N'适合平坦型数据的属性增删改查，支持搜索、表格列表、弹窗/抒屉表单编辑','mdi:table',N'当前模板为「标准 CRUD」，请确保：\n1. columnsSchema 包含内容列 + 操作列(actions)\n2. editSchema 简洁清晰，不要嵌套\n3. modalType 默认为 drawer\n4. 尽量岑减搜索条件，保留最常用的3-5个',NULL,'{"modalType": "drawer", "modalWidth": "800px", "editGridCols": 1, "searchGridCols": 4}',1,1,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-26 17:20:22',0),(2,'tree-crud',N'树形 CRUD',N'适合具有父子层级结构的数据，如部门结构、分类管理等，左树右表格布局','mdi:file-tree',N'当前模板为「树形 CRUD」，请确保：\n1. editSchema 中必须包含 parentId 字段（type: treeSelect）\n2. editSchema 中包含 sort 排序字段\n3. columnsSchema 中包含 层级深度或父层名称列\n4. apiConfig 中包含 tree 接口（查询树形结构）\n5. treeConfig 配置：{"keyField": "id", "parentField": "parentId", "labelField": "name"}\n6. 数据必须有 parent_id 字段，不要导入进 editSchema\n7. 模式必须为 modal','{"treeConfig": {"keyField": "id", "labelField": "name", "parentField": "parentId"}}','{"modalType": "modal", "modalWidth": "600px", "editGridCols": 1, "searchGridCols": 3}',1,2,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-30 15:53:18',0);
GO

