INSERT INTO [ai_prompt_template] ([id], [tenant_id], [template_name], [template_code], [usage_scene], [business_category], [domain_category], [template_tags], [description], [prompt_content], [example_input], [status], [del_flag], [is_recommended], [sort_order], [use_count], [test_count], [download_count], [remark], [create_by], [create_time], [create_dept], [update_by], [update_time]) VALUES (1910000000000000001,1,N'数据驱动大屏生成通用模板','dashboard_generate_default','dashboard_generate',N'经营分析',N'数据大屏',N'数据绑定,经营监控,可视化',N'适用于基于业务定义和数据集生成可落地的大屏，强调动态数据绑定和组件布局。',N'请基于当前业务定义、数据集字段和运行时样例生成数据大屏。要求：\n1. 优先使用真实 datasetId 生成动态数据组件，指标、趋势、排行、表格、地图尽量输出 request.datasetId、request.datasetFields 和 request.datasetMapping。\n2. 先规划顶部 KPI、核心趋势、分类排行、明细/告警等区域，再选择合适组件，避免只生成装饰元素。\n3. 字段只能使用上下文中出现的 fieldName，不要使用字段中文名作为 request 字段。\n4. 敏感或隐藏字段按上下文安全规则处理，不能展示原始敏感值。\n5. 如果数据集不可用，可以静态兜底，但标题、说明和组件含义必须贴合业务目标。\n6. 输出必须是系统要求的合法 JSON，不要添加 Markdown 包裹或额外解释。',N'生成经营监控大屏，突出核心指标、趋势分析和异常预警。','0',0,'1',1,8,18,5,N'系统内置最佳实践模板',1,'2026-05-19 15:22:05',1,1,'2026-07-13 17:59:05');
GO

